import java.security.MessageDigest;
import java.util.SortedMap;
import java.util.TreeMap;

// A consistent hash ring mapping keys to nodes, using virtual nodes to
// smooth out load distribution across physical machines.
public class ConsistentHashRing {
    private final SortedMap<Long, String> ring = new TreeMap<>();
    private final int virtualNodesPerPhysicalNode;

    public ConsistentHashRing(int virtualNodesPerPhysicalNode) {
        this.virtualNodesPerPhysicalNode = virtualNodesPerPhysicalNode;
    }

    public void addNode(String nodeId) {
        for (int i = 0; i < virtualNodesPerPhysicalNode; i++) {
            long position = hash(nodeId + "#" + i);
            ring.put(position, nodeId);
        }
    }

    public void removeNode(String nodeId) {
        for (int i = 0; i < virtualNodesPerPhysicalNode; i++) {
            ring.remove(hash(nodeId + "#" + i));
        }
    }

    public String getOwner(String key) {
        long position = hash(key);
        SortedMap<Long, String> tail = ring.tailMap(position);
        Long ownerKey = tail.isEmpty() ? ring.firstKey() : tail.firstKey();
        return ring.get(ownerKey);
    }

    private long hash(String input) {
        try {
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            byte[] digest = md5.digest(input.getBytes());
            long value = 0;
            for (int i = 0; i < 8; i++) {
                value = (value << 8) | (digest[i] & 0xff);
            }
            return value;
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

