from sortedcontainers import SortedDict

# A consistent hash ring mapping keys to nodes, using virtual nodes to
# smooth out load distribution across physical machines.
class ConsistentHashRing:
    def __init__(self, virtual_nodes_per_physical_node):
        self.ring = SortedDict()
        self.virtual_nodes_per_physical_node = virtual_nodes_per_physical_node

    def add_node(self, node_id):
        for i in range(self.virtual_nodes_per_physical_node):
            position = self._hash(f"{node_id}#{i}")
            self.ring[position] = node_id

    def remove_node(self, node_id):
        for i in range(self.virtual_nodes_per_physical_node):
            position = self._hash(f"{node_id}#{i}")
            if position in self.ring:
                del self.ring[position]

    def get_owner(self, key):
        position = self._hash(key)
        keys = self.ring.keys()
        idx = self.ring.bisect_left(position)
        if idx == len(keys):
            idx = 0
        return self.ring[keys[idx]]

    def _hash(self, value):
        digest = hashlib.md5(value.encode()).digest()
        return int.from_bytes(digest[:8], byteorder="big")

