// A consistent hash ring mapping keys to nodes, using virtual nodes to
// smooth out load distribution across physical machines.
class ConsistentHashRing {
    map<unsigned long long, string> ring;
    int virtualNodesPerPhysicalNode;

    unsigned long long hashValue(const string& input) {
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5((const unsigned char*)input.c_str(), input.size(), digest);
        unsigned long long value = 0;
        for (int i = 0; i < 8; i++) {
            value = (value << 8) | digest[i];
        }
        return value;
    }

public:
    ConsistentHashRing(int virtualNodes) : virtualNodesPerPhysicalNode(virtualNodes) {}

    void addNode(string nodeId) {
        for (int i = 0; i < virtualNodesPerPhysicalNode; i++) {
            ring[hashValue(nodeId + "#" + to_string(i))] = nodeId;
        }
    }

    void removeNode(string nodeId) {
        for (int i = 0; i < virtualNodesPerPhysicalNode; i++) {
            ring.erase(hashValue(nodeId + "#" + to_string(i)));
        }
    }

    string getOwner(string key) {
        unsigned long long position = hashValue(key);
        auto it = ring.lower_bound(position);
        if (it == ring.end()) it = ring.begin();
        return it->second;
    }
