import java.util.List;
import java.util.concurrent.*;

// Coordinates a write across N replicas, succeeding once W of them
// acknowledge, without waiting for the remaining, slower replicas.
public class QuorumCoordinator {
    private final int writeQuorum;

    public QuorumCoordinator(int writeQuorum) {
        this.writeQuorum = writeQuorum;
    }

    public boolean writeWithQuorum(List<StorageNode> replicas, String key, String value) throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(replicas.size());
        CountDownLatch latch = new CountDownLatch(writeQuorum);
        for (StorageNode replica : replicas) {
            pool.submit(() -> {
                boolean ok = replica.write(key, value);
                if (ok) latch.countDown();
            });
        }
        boolean metQuorum = latch.await(500, TimeUnit.MILLISECONDS);
        pool.shutdown();
        return metQuorum;
    }

    public interface StorageNode {
        boolean write(String key, String value);
    }
}

