#include <chrono>
#include <condition_variable>
#include <mutex>
#include <string>
#include <thread>
#include <vector>

struct StorageNode {
    virtual bool write(const std::string& key, const std::string& value) = 0;
    virtual ~StorageNode() = default;
};

// Coordinates a write across N replicas, succeeding once W of them
// acknowledge, without waiting for the remaining, slower replicas.
class QuorumCoordinator {
public:
    explicit QuorumCoordinator(int writeQuorum) : writeQuorum_(writeQuorum) {}

    bool writeWithQuorum(const std::vector<StorageNode*>& replicas, const std::string& key, const std::string& value) {
        std::mutex mu;
        std::condition_variable cv;
        int acked = 0;
        bool quorumMet = false;

        std::vector<std::thread> threads;
        for (StorageNode* replica : replicas) {
            threads.emplace_back([&, replica]() {
                bool ok = replica->write(key, value);
                if (ok) {
                    std::lock_guard<std::mutex> lock(mu);
                    acked++;
                    if (acked >= writeQuorum_) { quorumMet = true; cv.notify_all(); }
                }
            });
        }

        {
            std::unique_lock<std::mutex> lock(mu);
            cv.wait_for(lock, std::chrono::milliseconds(500), [&] { return quorumMet; });
        }
        for (auto& t : threads) t.join();
        return quorumMet;
    }

private:
    int writeQuorum_;
};

