import java.util.HashMap;
import java.util.Map;

// Tracks causal history per node so the system can distinguish "this write
// happened before that one" from "these two writes were truly concurrent."
public class VectorClock {
    private final Map<String, Integer> versions = new HashMap<>();

    public void increment(String nodeId) {
        versions.merge(nodeId, 1, Integer::sum);
    }

    public boolean isConcurrentWith(VectorClock other) {
        boolean thisHasGreater = false;
        boolean otherHasGreater = false;
        for (String nodeId : union(other)) {
            int a = versions.getOrDefault(nodeId, 0);
            int b = other.versions.getOrDefault(nodeId, 0);
            if (a > b) thisHasGreater = true;
            if (b > a) otherHasGreater = true;
        }
        return thisHasGreater && otherHasGreater;
    }

    private Iterable<String> union(VectorClock other) {
        Map<String, Integer> merged = new HashMap<>(versions);
        merged.putAll(other.versions);
        return merged.keySet();
    }
}

