    bool isConcurrentWith(const VectorClock& other) const {
        bool thisHasGreater = false;
        bool otherHasGreater = false;
        std::set<std::string> allNodes;
        for (auto& [k, v] : versions_) allNodes.insert(k);
        for (auto& [k, v] : other.versions_) allNodes.insert(k);
        for (auto& nodeId : allNodes) {
            int a = versions_.count(nodeId) ? versions_.at(nodeId) : 0;
            int b = other.versions_.count(nodeId) ? other.versions_.at(nodeId) : 0;
            if (a > b) thisHasGreater = true;
            if (b > a) otherHasGreater = true;
        }
        return thisHasGreater && otherHasGreater;
    }

private:
    std::map<std::string, int> versions_;
};

